from flask import Flask, Response
import sys

import json
import os

# Graft generated by Graftcode Gateway from grpc-services/users/graft (see README)
from graft_pypi_users_service import GraftConfig
from graft_pypi_users_service.graft.users_graft import Users

GraftConfig.host = os.environ.get('USERS_HOST', 'ws://users:50051/ws')

app = Flask(__name__)

@app.route("/healthz")
def ping():
    return "ok", 200

@app.route('/users/')
def users_get():
    app.config['users'] = Users
    request = (["alexa", "christie"], [1, 1])
    def get_user():
        response = app.config['users'].get_users(*request)
        for resp in response:
            yield json.dumps({"user": {"username": resp.username, "userId": resp.user_id}}, indent=2)
    return Response(get_user(), content_type='application/json')